public class ByteToString {
    public static void main(String[] args) {
        // Convert a byte array directly to a string
        String directConversion = new String(new byte[]{1, 2, 3}, StandardCharsets.UTF_8);
        System.out.println("Direct conversion: " + directConversion);

        // Use the toString() method with default encoding (UTF-8)
        String defaultEncodingConversion = new String(new byte[]{1, 2, 3}, StandardCharsets.UTF_8);
        System.out.println("Default encoding conversion: " + defaultEncodingConversion);

        // Use the getChars() method to convert a byte array to a string
        String getCharsConversion = "Hello, World!";
        int[] buffer = new int[1024];
        getChars(0, 10, buffer, 1);
        System.out.println("GetChars conversion: " + getCharsConversion);

        // Use the replace() method to remove bytes that represent non-printable characters
        String replaceConversion = "Hello! World?";
        for (int i = 0; i < Math.min(1024, replaceConversion.length()); i++) {
            if (!Character.isDigit(replaceConversion.charAt(i))) {
                replaceConversion = replaceConversion.substring(0, i) + replaceConversion.substring(i + 1);
            }
        }
        System.out.println("Replace conversion: " + replaceConversion);

        // Use the decode() method with ISO-8859-1 encoding
        String isoEncodingConversion = new String(new byte[]{1, 2, 3}, StandardCharsets.ISO_8859_1);
        System.out.println("ISO-8859-1 encoding conversion: " + isoEncodingConversion);

        // Use the encode() method with UTF-8 encoding
        String utf8Conversion = new String(new byte[]{1, 2, 3}, StandardCharsets.UTF_8);
        System.out.println("UTF-8 encoding conversion: " + utf8Conversion);
    }

    public static void getChars(int offset, int count, byte[] buffer, int pointer) {
        for (int i = 0; i < count; i++) {
            if (offset + i >= buffer.length) break;
            buffer[pointer + i] = buffer[offset + i];
        }
    }
}
